import{_ as e,o as s,c as t,a2 as r}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"Worker 租约、失败分类与恢复","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/job-recovery","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/job-recovery.md","filePath":"tutorials/job-recovery.md"}'),n={name:"tutorials/job-recovery.md"};function i(o,a,d,c,l,p){return s(),t("div",null,[...a[0]||(a[0]=[r(`<h1 id="worker-租约、失败分类与恢复" tabindex="-1">Worker 租约、失败分类与恢复 <a class="header-anchor" href="#worker-租约、失败分类与恢复" aria-label="Permalink to &quot;Worker 租约、失败分类与恢复&quot;">​</a></h1><p>目标：让自己的后台任务在进程崩溃、外部服务故障和管理员重试后仍遵守有限预算。前提是实现了<a href="./document-exports">Handler 与发布事务</a>；Jobs 提供可靠执行协调，外部副作用仍需业务幂等。</p><h2 id="领取也消耗一次尝试" tabindex="-1">领取也消耗一次尝试 <a class="header-anchor" href="#领取也消耗一次尝试" aria-label="Permalink to &quot;领取也消耗一次尝试&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">Core Jobs</a>在领取事务增加 attempts、生成独立 lease_token 并记录 attempt。领取后立刻崩溃也消耗预算；租约到期后，其他 Worker 只能在剩余预算内重新领取。预算耗尽转 failed，不无限重领。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stateDiagram-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  queued --&gt; running: claim / attempts + 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  running --&gt; succeeded: fenced commit</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  running --&gt; retry_wait: transient / budget remains</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  retry_wait --&gt; running: scheduled claim</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  running --&gt; failed: permanent or exhausted</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  failed --&gt; queued: explicit admin batch</span></span></code></pre></div><p><code>JobError::Transient(&quot;static.code&quot;)</code> 有界退避重试，采用指数退避/full jitter；<code>Permanent</code> 进入失败终态；<code>LostLease</code> 不允许旧执行者写终态。只保存静态安全码，不格式化存储错误、payload 或秘密到摘要。</p><h2 id="fence-保护结果" tabindex="-1">fence 保护结果 <a class="header-anchor" href="#fence-保护结果" aria-label="Permalink to &quot;fence 保护结果&quot;">​</a></h2><p><code>Lease::lock_current(connection)</code> 要求当前 token、running、期限有效并取行锁；<code>succeed(connection)</code> 在调用者事务更新 Job、attempt/batch 和通知。业务结果、Audit、succeed 同事务提交。签名见<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">源码</a>。</p><p>第二个 Worker 接手后，第一个即使完成 I/O 也不能用旧 token 覆盖结果。fence 不能撤销已经发送的邮件或远端动作；使用不可覆盖候选、业务唯一约束或服务端幂等键控制副作用。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer">Worker 循环</a>独立驱动 Handler 和 heartbeat；续租 SQL 等待发布锁时 Handler 仍推进。续租失败先取消 Handler future、释放事务，再有界写失败。关停停止新领取并有限 drain，超时保留 running 租约等待到期，不提前释放仍执行副作用的任务。</p><p>默认 lease/heartbeat/drain 为 60/20/10 秒，配置见<a href="./../reference/config">参考</a>。阻塞工作仍需协作取消，<code>spawn_blocking</code> 开始后不能强制中止。</p><h2 id="复用管理员恢复" tabindex="-1">复用管理员恢复 <a class="header-anchor" href="#复用管理员恢复" aria-label="Permalink to &quot;复用管理员恢复&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/management.rs" target="_blank" rel="noreferrer">管理 API</a>和<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/jobs/administration.rs" target="_blank" rel="noreferrer">用例</a>只允许当前 Owner/Admin 查询或重试。失败重试保留 Job ID、业务 payload/快照，显式开启新的有限 batch，旧历史不删除；幂等命令和 Audit 同事务，成功任务不能重开。</p><p>管理响应不返回 payload 或 lease_token。列表 cursor 绑定身份/状态，详情有界加载历史。恢复外部服务后可以重试临时失败；原凭据撤销、资源失权或快照过期不会因管理员重试恢复，应由合法用户新申请。</p><h2 id="可控故障验证" tabindex="-1">可控故障验证 <a class="header-anchor" href="#可控故障验证" aria-label="Permalink to &quot;可控故障验证&quot;">​</a></h2><p>仓库根目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jobs</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exports</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/jobs.rs" target="_blank" rel="noreferrer">公开 Jobs 测试</a>验证崩溃次数、租约接替、旧结果拒绝、有限关停和退避；<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/apps/api/tests/jobs.rs" target="_blank" rel="noreferrer">管理测试</a>验证权限、新 batch、历史、幂等和审计回滚。竞态用真实锁与同步点，时间边界推进数据库时间戳，不靠随机 sleep。</p><p>自己的 Handler 增加“领取后失去租约仍不能发布”的检查，再定义永久/临时错误分类。下一步接入<a href="./deletion-cleanup">业务删除与清理</a>；已登记的通知由<a href="./export-notifications">终态事务</a>发布。</p><hr><p>源码版本：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/tutorials/11-job-recovery.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,22)])])}const u=e(n,[["render",i]]);export{b as __pageData,u as default};
